def compute(vars):
    old_value = vars["v2"]
    new_value = vars["v1"]
    increase = new_value - old_value
    percentage_increase = increase / old_value * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "increase": increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
